/* insertCompnoChcTypeMngNo (복수선택유형 테이블 PK insert) - Lee Hye Sun */
INSERT INTO AFA130(
     COMPNO_CHC_TYPE_MNG_NO
     , FRST_RGTR_ID
     , FRST_REG_DT
     , LAST_MDFR_ID
     , LAST_MDFCN_DT
) VALUES (
       #{COMPNO_CHC_TYPE_MNG_NO}
     , #{FRST_RGTR_ID}
     , SYSDATE
     , #{LAST_MDFR_ID}
     , SYSDATE
)

/* insertCompnoChcTypeDtl (복수선택유형상세 insert) - Lee Hye Sun */
INSERT INTO AFA131 (
      COMPNO_CHC_TYPE_MNG_NO        /*복수선택유형관리번호*/
    , COMPNO_CHC_TYPE_DTL_SN        /*복수선택유형상세일련번호*/
    , COMPNO_TYPE_LCLAS_SE_CD       /*복수유형대분류구분코드*/
    , COMPNO_TYPE_MLSFC_SE_CD       /*복수유형중분류구분코드*/
    , COMPNO_TYPE_SCLAS_SE_CD       /*복수유형소분류구분코드*/
    , COMPNO_CHC_TYPE_ETC_NM        /*복수선택유형기타명*/
    , FRST_RGTR_ID              
    , FRST_REG_DT
    , LAST_MDFR_ID
    , LAST_MDFCN_DT
) VALUES (
      #{COMPNO_CHC_TYPE_MNG_NO}
    , (SELECT NVL(MAX(CAST(COMPNO_CHC_TYPE_DTL_SN AS NUMBER)),0) +1 FROM AFA131
      WHERE COMPNO_CHC_TYPE_MNG_NO = #{COMPNO_CHC_TYPE_MNG_NO})
    , SUBSTR(#{COMPNO_TYPE_SCLAS_SE_CD}, 0, 2)
    , SUBSTR(#{COMPNO_TYPE_SCLAS_SE_CD}, 0, 4)
    , #{COMPNO_TYPE_SCLAS_SE_CD}
    , #{COMPNO_CHC_TYPE_ETC_NM}
    , #{FRST_RGTR_ID}
    , SYSDATE
    , #{LAST_MDFR_ID}
    , SYSDATE
)

