/* selectAdhrncWrtcnsChck 참가자동의서 작성상태 체크 > AFA110 체크 - Lee Seoung Jae */

SELECT
   COUNT(*)
FROM AFA110     /* 참가자동의내역 */

WHERE 1=1
AND TRPR_INFO_NO = #{TRPR_INFO_NO}
AND APLY_RCPT_SN = #{APLY_RCPT_SN}


        /* chkCreateQustnbMngNoYn 설문지관리번호 생성 조회 > SBB110 체크 - Kim Seong Ok */

        SELECT 
            QUSTNB_MNG_NO           /* 설문지관리번호 */
            , QUSTNB_TMPT_MNG_NO    /* 설문지템플릿관리번호 */
        FROM SBB110 
			WHERE 1=1
			AND CASE_MNG_NO = #{CASE_MNG_NO}
			AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
			AND TRPR_INFO_NO = #{TRPR_INFO_NO}
			AND QUSTNB_TMPT_MNG_NO = #{QUSTNB_TMPT_MNG_NO}
			AND TRPR_REL_SE_CD = #{TRPR_REL_SE_CD}

mapper.insert:
SELECT NVL(MAX(MNG_SN)+1 ,1) FROM SBB600 WHERE INST_NO = #{INST_NO} AND REG_YMD = TO_CHAR(SYSDATE, 'YYYYMMDD')
/*SQL-ID : isry.csems.mngrpage.aplcnttrprdtlinfomng.mapper.AplcntTrprDtlInfoMngMapper insertQustnbSndngHstr : 설문발송이력 SBB600 */
INSERT INTO SBB600 ( INST_NO /* 기관번호 */ ,REG_YMD /* 등록일자 */ ,MNG_SN /* 관리일련번호 */ ,UNT_TASKWK_SE_CD /* 단위업무구분코드 */ ,TRPR_INFO_NO /* 대상자정보번호 */ ,CASE_MNG_NO /* 사례관리번호 */ ,CASE_MNG_ODRNO /* 사례관리차수 */ ,TRPR_REL_SE_CD /* 대상자관계구분코드 */ ,QUSTNB_MNG_NO /* 설문지관리번호 */ ,QUSTNB_TMPT_MNG_NO /* 설문지템플릿관리번호 */ ,SRVY_ERA_SE_CD /* 설문시기구분코드 */ ,NO_INPT_SNDNG_YN /* 번호입력발송여부 */ ,SRVY_RSPDNT_NM_ENCPT /* 설문응답자명암호화 */ ,SRVY_RSPNS_RCPTN_MBL_TELNO_ENCPT /* 설문응답수신휴대전화번호암호화 */ ,SNDNG_DT /* 발송일시 */ ,SRVY_RCPTN_MTHD_SE_CD /* 설문수신방법구분코드 */ ,FRST_RGTR_ID /* 최초등록자아이디 */ ,FRST_REG_DT /* 최초등록일시 */ ,LAST_MDFR_ID /* 최종수정자아이디 */ ,LAST_MDFCN_DT /* 최종수정일시 */ ) VALUES ( #{INST_NO}, /* 기관번호 */ TO_CHAR(SYSDATE, 'YYYYMMDD'), /* 등록일자 */ #{MNG_SN}, /* 관리일련번호 */ (SELECT UNT_TASKWK_SE_CD FROM SBB000 WHERE QUSTNB_TMPT_MNG_NO = #{QUSTNB_TMPT_MNG_NO}), #{TRPR_INFO_NO}, /* 대상자정보번호 */ #{CASE_MNG_NO}, /* 사례관리번호 */ #{CASE_MNG_ODRNO}, /* 사례관리차수 */ #{TRPR_REL_SE_CD}, /* 대상자관계구분코드 */ #{QUSTNB_MNG_NO}, /* 설문지관리번호 */ #{QUSTNB_TMPT_MNG_NO}, /* 설문지템플릿관리번호 */ #{SRVY_ERA_SE_CD}, /* 설문시기구분코드 */ #{NO_INPT_SNDNG_YN}, /* 번호입력발송여부 */ ENC_B64(#{SRVY_RSPDNT_NM_ENCPT}), /* 설문응답자명암호화 */ ENC_B64(#{SRVY_RSPNS_RCPTN_MBL_TELNO_ENCPT}), /* 설문응답수신휴대전화번호암호화 */ SYSDATE, /* 발송일시 */ #{SRVY_RCPTN_MTHD_SE_CD}, /* 설문수신방법구분코드 */ #{FRST_RGTR_ID}, /* 최초등록자아이디 */ SYSDATE, /* 최초등록일시 */ #{LAST_MDFR_ID}, /* 최종수정자아이디 */ SYSDATE /* 최종수정일시 */ )

mapper.select:

        /* srvyWrtStts 설문작성여부 생성 조회 > SBB500 체크 - Kim Seong Ok */

        SELECT
		     CASE WHEN COUNT(*) IS NULL THEN '02'
		     ELSE '01'
		     END AS  SRVY_WRT_STTS_SE_CD
		 FROM (
		    SELECT
		        RSPNS_DT
		     FROM SBB500 
		     WHERE 1=1
		     AND QUSTNB_MNG_NO = #{QUSTNB_MNG_NO}
		     AND QUSTNB_TMPT_MNG_NO = #{QUSTNB_TMPT_MNG_NO}
		     AND USER_ID = #{USER_ID}
		     AND UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
		     AND CASE_MNG_NO = #{CASE_MNG_NO}
		     AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
		 ) T
